console.log("=== Testing __proto__ pollution ===");

// Clean state check
const before = ({} as any).polluted;
console.log("Before test, ({}).polluted:", before);

// Parse a malicious JSON payload with __proto__
const payload = JSON.parse('{"__proto__":{"polluted":true}}');
console.log("Parsed payload:", payload);
console.log("payload.__proto__:", payload.__proto__);
console.log("Object.getPrototypeOf(payload):", Object.getPrototypeOf(payload));
console.log("Object.prototype.hasOwnProperty('polluted'):", Object.prototype.hasOwnProperty("polluted"));

// Attempt the merge
console.log("\nCalling defu({}, payload)...");
const result = defu({}, payload);
console.log("Result:", result);

// Check if prototype was polluted
console.log("\n=== After defu({}, payload) ===");
console.log("( {} as any ).polluted:", ({} as any).polluted);
console.log("Object.prototype.hasOwnProperty('polluted'):", Object.prototype.hasOwnProperty("polluted"));

// Additional test: defu(payload, {})
console.log("\nCalling defu(payload, {})...");
const payload2 = JSON.parse('{"__proto__":{"polluted2":true}}');
const result2 = defu(payload2, {});
console.log("( {} as any ).polluted2:", ({} as any).polluted2);
console.log("Object.prototype.hasOwnProperty('polluted2'):", Object.prototype.hasOwnProperty("polluted2"));

// Final verdict
const isPolluted = ({} as any).polluted === true || ({} as any).polluted2 === true;
console.log("\n=== VERDICT ===");
if (isPolluted) {
  console.log("❌ BUG CONFIRMED: Object.prototype was polluted!");
  process.exit(1);
} else {
  console.log("✅ No pollution detected");
  process.exit(0);
}

