console.log('Object.getPrototypeOf(object1):', Object.getPrototypeOf(object1));
console.log('Object.prototype.polluted:', ({} as any).polluted);

// Step 2: for (const key in baseObject) - baseObject is payload here
// The loop iterates __proto__, but it's skipped by the if check
// So nothing happens there

// Step 3: return object
// So the result is object1 which has polluted: true as own property
console.log('\\nResult is object1:', object1);
console.log('object1.hasOwnProperty(\"polluted\"):', object1.hasOwnProperty('polluted'));
console.log('object1.polluted:', object1.polluted);

// But what about when we do defu(payload, {})? Let's trace that
// _defu(payload, {})
// isPlainObject({}) = true
// object = Object.assign({}, {}) = {}
// for key in payload: __proto__
// key === __proto__ -> continue
// So nothing happens, returns {}
// That shouldn't pollute anything

// Let's try with object[key] = value where object.__proto__ is already set
console.log('\\n--- Testing prototype chain mutation ---');
const a = Object.assign({}, payload); // a has __proto__ = {polluted:true}
console.log('a.__proto__:', a.__proto__);
