import { describe, test, expect, afterEach } from "vitest";
import { defu, createDefu, defuFn, defuArrayFn } from "../src/defu.ts";

// Helper to check Object.prototype pollution
function isObjectPrototypePolluted(): string[] {
  const dangerousKeys = [
    "polluted",
    "isAdmin",
    "inner",
    "polluted2",
    "polluted3",
    "polluted4",
    "polluted5",
    "__polluted__",
  ];
  return dangerousKeys.filter((k) => (Object.prototype as any)[k] !== undefined);
}

describe("__proto__ pollution invariants", () => {
  afterEach(() => {
    // Clean up any pollution from tests
    delete (Object.prototype as any).polluted;
    delete (Object.prototype as any).isAdmin;
    delete (Object.prototype as any).inner;
    delete (Object.prototype as any).polluted2;
    delete (Object.prototype as any).polluted3;
    delete (Object.prototype as any).polluted4;
    delete (Object.prototype as any).polluted5;
    delete (Object.prototype as any).__polluted__;
  });

  test("defu treats __proto__ as regular own property (defaults position)", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu({}, payload);

    expect(result).toHaveProperty("__proto__");
    expect((result as any).__proto__).toEqual({ polluted: true });
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty("__proto__")).toBe(true);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });

  test("defu treats __proto__ as regular own property (baseObject position)", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defu(payload, {});

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });

  test("defu with __proto__ in both positions", () => {
    const base = JSON.parse('{"__proto__":{"polluted":true}}');
    const defaults = JSON.parse('{"__proto__":{"polluted2":true}}');
    const result = defu(base, defaults);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((Object.prototype as any).polluted).toBeUndefined();
    expect((Object.prototype as any).polluted2).toBeUndefined();
  });

  test("defu with __proto__ alongside regular properties", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true},"a":"b","c":42}');
    const result = defu({}, payload);

    expect(result).toEqual({ __proto__: { polluted: true }, a: "b", c: 42 });
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });

  test("defu with nested __proto__", () => {
    const payload = JSON.parse(
      '{"a":{"__proto__":{"polluted":true}},"__proto__":{"polluted2":true}}',
    );
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((result as any).a).toHaveProperty("__proto__");
    expect((Object.prototype as any).polluted).toBeUndefined();
    expect((Object.prototype as any).polluted2).toBeUndefined();
  });

  test("defu with constructor.prototype attack is blocked", () => {
    const payload = JSON.parse(
      '{"constructor":{"prototype":{"isAdmin":true}}}',
    );
    defu({}, payload);

    expect((Object.prototype as any).isAdmin).toBeUndefined();
  });

  test("defu with deeply nested constructor.prototype attack", () => {
    const payload = JSON.parse(
      '{"__proto__":{"constructor":{"prototype":{"isAdmin":true}}}}',
    );
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((Object.prototype as any).isAdmin).toBeUndefined();
  });

  test("defu multi-arg merge does not pollute", () => {
    const p1 = JSON.parse('{"__proto__":{"polluted":true}}');
    const p2 = JSON.parse('{"__proto__":{"polluted2":true}}');
    const p3 = JSON.parse('{"__proto__":{"polluted3":true}}');

    defu({}, p1, p2, p3);

    expect((Object.prototype as any).polluted).toBeUndefined();
    expect((Object.prototype as any).polluted2).toBeUndefined();
    expect((Object.prototype as any).polluted3).toBeUndefined();
  });

  test("defuFn treats __proto__ as regular own property", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defuFn({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty("__proto__")).toBe(true);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });

  test("defuArrayFn treats __proto__ as regular own property", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = defuArrayFn({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty("__proto__")).toBe(true);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });

  test("createDefu with custom merger treats __proto__ as regular own property", () => {
    const customDefu = createDefu();
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const result = customDefu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty("__proto__")).toBe(true);
    expect((Object.prototype as any).polluted).toBeUndefined();
  });
});

describe("concurrent async merge invariants", () => {
  test("concurrent defu calls do not interfere", async () => {
    const payloads = Array.from({ length: 100 }, (_, i) =>
      JSON.parse(`{"__proto__":{"polluted${i}":true},"key${i}":"value${i}"}`),
    );

    const results = await Promise.all(
      payloads.map((p) => Promise.resolve(defu({}, p))),
    );

    expect((Object.prototype as any).polluted0).toBeUndefined();
    expect((Object.prototype as any).polluted99).toBeUndefined();

    for (const result of results) {
      expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    }
  });

  test("rapid sequential defu calls do not pollute", () => {
    for (let i = 0; i < 1000; i++) {
      const payload = JSON.parse(
        `{"__proto__":{"polluted${i}":true},"key":"value${i}"}`,
      );
      defu({}, payload);
    }

    // Check a sampling of the keys
    for (let i = 0; i < 1000; i++) {
      expect((Object.prototype as any)[`polluted${i}`]).toBeUndefined();
    }
  });

  test("interleaved defu and plain object operations", () => {
    const payload = JSON.parse('{"__proto__":{"polluted":true}}');
    const results: any[] = [];

    for (let i = 0; i < 50; i++) {
      results.push(defu({}, payload));
      // Intersperse plain object operations
      const plain = { x: i };
      expect(plain.x).toBe(i);
    }

    expect((Object.prototype as any).polluted).toBeUndefined();
    for (const r of results) {
      expect(Object.getPrototypeOf(r)).toBe(Object.prototype);
    }
  });
});

describe("boundary and edge cases", () => {
  test("empty __proto__ value", () => {
    const payload = JSON.parse('{"__proto__":{}}');
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect(result.hasOwnProperty("__proto__")).toBe(true);
  });

  test("__proto__ with null value", () => {
    const payload = JSON.parse('{"__proto__":null}');
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
  });

  test("__proto__ with primitive value", () => {
    const payload = JSON.parse('{"__proto__":"string"}');
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((result as any).__proto__).toBe("string");
  });

  test("__proto__ with deeply nested object", () => {
    const deep = { a: { b: { c: { d: { e: true } } } } };
    const payload = JSON.parse(`{"__proto__":${JSON.stringify(deep)}}`);
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((result as any).__proto__).toEqual(deep);
  });

  test("null defaults does not crash", () => {
    const result = defu({ a: 1 }, null);
    expect(result).toEqual({ a: 1 });
  });

  test("undefined defaults does not crash", () => {
    const result = defu({ a: 1 }, undefined);
    expect(result).toEqual({ a: 1 });
  });

  test("empty objects merge correctly", () => {
    const result = defu({}, {});
    expect(result).toEqual({});
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
  });

  test("defu with only __proto__ key", () => {
    const payload = JSON.parse('{"__proto__":{"x":1}}');
    const result = defu(payload, {});

    expect(result).toHaveProperty("__proto__");
    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
  });

  test("multiple __proto__-like keys", () => {
    const payload = JSON.parse(
      '{"__proto__":{"polluted":true},"constructor":{"prototype":{"isAdmin":true}},"toString":"overridden"}',
    );
    const result = defu({}, payload);

    expect(Object.getPrototypeOf(result)).toBe(Object.prototype);
    expect((Object.prototype as any).polluted).toBeUndefined();
    expect((Object.prototype as any).isAdmin).toBeUndefined();
    expect(typeof ({}).toString).toBe("function"); // toString not overridden
  });

  test("Object.prototype remains clean after all operations", () => {
    // Record all keys on Object.prototype before
    const keysBefore = Object.getOwnPropertyNames(Object.prototype);

    defu({}, JSON.parse('{"__proto__":{"x":1}}'));
    defu({}, JSON.parse('{"__proto__":{"y":2}}'));
    defu({}, JSON.parse('{"constructor":{"prototype":{"z":3}}}'));

    const keysAfter = Object.getOwnPropertyNames(Object.prototype);
    expect(keysAfter).toEqual(keysBefore);
  });
});

